package closure_test

import (
	"encoding/json"
	"testing"

	"github.com/SukramJ/openccu-loom/internal/north/matter/cluster/closure"
	clusterwire "github.com/SukramJ/openccu-loom/internal/north/matter/cluster/wire"
	matterparity "github.com/SukramJ/openccu-loom/internal/north/matter/parity"
)

// The subset of the matter.js schema snapshot these tests read. The
// snapshot is the matter.js HEAD pin regenerated by
// `make generate-matter-schema`, so asserting against it is asserting
// against matter.js rather than against a second hand-typed copy of the
// same numbers — which would agree with the code and with nothing else.
type (
	matterFieldEntry struct {
		ID          uint32 `json:"id"`
		Name        string `json:"name"`
		Conformance string `json:"conformance"`
	}
	matterFeatureEntry struct {
		Name        string `json:"name"`
		Conformance string `json:"conformance"`
	}
	matterClusterEntry struct {
		ID         uint32               `json:"id"`
		Name       string               `json:"name"`
		Revision   uint16               `json:"revision"`
		Attributes []matterFieldEntry   `json:"attributes"`
		Commands   []matterFieldEntry   `json:"commands"`
		Events     []matterFieldEntry   `json:"events"`
		Features   []matterFeatureEntry `json:"features"`
	}
	matterSchemaEnvelope struct {
		Clusters []matterClusterEntry `json:"clusters"`
	}
)

func closureSchema(t *testing.T) matterClusterEntry {
	t.Helper()
	var s matterSchemaEnvelope
	if err := json.Unmarshal(matterparity.SchemaJSON(), &s); err != nil {
		t.Fatalf("unmarshal matter-schema-snapshot.json: %v", err)
	}
	for i := range s.Clusters {
		if s.Clusters[i].ID == clusterwire.ClosureControlClusterID {
			return s.Clusters[i]
		}
	}
	t.Fatalf("matter.js schema has no cluster 0x%04X (ClosureControl)", clusterwire.ClosureControlClusterID)
	return matterClusterEntry{}
}

// idOf resolves a named element's ID from the schema, failing when
// matter.js no longer carries that name. A rename is a drift the port has
// to follow, not a case to skip over.
func idOf(t *testing.T, kind string, entries []matterFieldEntry, name string) uint32 {
	t.Helper()
	for _, e := range entries {
		if e.Name == name {
			return e.ID
		}
	}
	t.Fatalf("matter.js ClosureControl has no %s named %q", kind, name)
	return 0
}

// TestParityMatterJS_ClosureControlClusterRevision pins the cluster
// revision against matter.js HEAD.
func TestParityMatterJS_ClosureControlClusterRevision(t *testing.T) {
	t.Parallel()
	js := closureSchema(t)
	if closure.ClusterRevision != js.Revision {
		t.Errorf("ClusterRevision = %d, want %d (matter.js HEAD for %s 0x%04X)",
			closure.ClusterRevision, js.Revision, js.Name, js.ID)
	}
}

// TestParityMatterJS_ClosureControlAttributeIDs pins every attribute-ID
// constant against matter.js HEAD by name.
func TestParityMatterJS_ClosureControlAttributeIDs(t *testing.T) {
	t.Parallel()
	js := closureSchema(t)
	cases := []struct {
		name string
		got  uint32
	}{
		{"CountdownTime", clusterwire.ClosureControlAttrCountdownTime},
		{"MainState", clusterwire.ClosureControlAttrMainState},
		{"CurrentErrorList", clusterwire.ClosureControlAttrCurrentErrorList},
		{"OverallCurrentState", clusterwire.ClosureControlAttrOverallCurrentState},
		{"OverallTargetState", clusterwire.ClosureControlAttrOverallTargetState},
		{"LatchControlModes", clusterwire.ClosureControlAttrLatchControlModes},
	}
	for _, tc := range cases {
		if want := idOf(t, "attribute", js.Attributes, tc.name); tc.got != want {
			t.Errorf("%s = 0x%04X, want 0x%04X (matter.js HEAD)", tc.name, tc.got, want)
		}
	}
}

