// TestParityMatterJS_ClosureControlFeatureBits pins each feature bit
// against its position in matter.js's feature list.
//
// The snapshot carries features in declaration order and the Matter
// FeatureMap assigns bit N to the Nth declared feature, so the index is
// the bit. A feature inserted upstream shifts every later bit, which is
// exactly the drift this catches — and the kind that produces a
// FeatureMap a controller reads as a different device.
func TestParityMatterJS_ClosureControlFeatureBits(t *testing.T) {
	t.Parallel()
	js := closureSchema(t)
	cases := []struct {
		name string
		got  uint32
	}{
		{"PS", clusterwire.ClosureControlFeaturePositioning},
		{"LT", clusterwire.ClosureControlFeatureMotionLatching},
		{"IS", clusterwire.ClosureControlFeatureInstantaneous},
		{"SP", clusterwire.ClosureControlFeatureSpeed},
		{"VT", clusterwire.ClosureControlFeatureVentilation},
		{"PD", clusterwire.ClosureControlFeaturePedestrian},
		{"CL", clusterwire.ClosureControlFeatureCalibration},
		{"PT", clusterwire.ClosureControlFeatureProtection},
		{"MO", clusterwire.ClosureControlFeatureManuallyOperable},
	}
	for _, tc := range cases {
		bit := -1
		for i, f := range js.Features {
			if f.Name == tc.name {
				bit = i
				break
			}
		}
		if bit < 0 {
			t.Errorf("matter.js ClosureControl has no feature %q", tc.name)
			continue
		}
		if want := uint32(1) << uint(bit); tc.got != want {
			t.Errorf("feature %s = 0x%X, want 0x%X (bit %d in matter.js HEAD declaration order)",
				tc.name, tc.got, want, bit)
		}
	}
}

// TestParityMatterJS_ClosureControlVentilationRequiresPositioning pins the
// conformance rule behind the advertised feature map.
//
// Ventilation is "[PS]" in matter.js, so a server advertising VT without
// PS describes a device the spec does not allow. Nothing at runtime
// rejects that combination — a controller simply reads a feature map that
// does not add up.
func TestParityMatterJS_ClosureControlVentilationRequiresPositioning(t *testing.T) {
	t.Parallel()
	js := closureSchema(t)

	var ventConformance string
	for _, f := range js.Features {
		if f.Name == "VT" {
			ventConformance = f.Conformance
		}
	}
	if ventConformance != "[PS]" {
		t.Fatalf("matter.js VT conformance = %q, want \"[PS]\" — the feature map below assumes it", ventConformance)
	}

	fm := closure.PositioningVentilationFeatureMap
	if fm&clusterwire.ClosureControlFeatureVentilation == 0 {
		t.Error("PositioningVentilationFeatureMap does not advertise Ventilation")
	}
	if fm&clusterwire.ClosureControlFeaturePositioning == 0 {
		t.Error("PositioningVentilationFeatureMap advertises Ventilation without Positioning, " +
			"which its \"[PS]\" conformance forbids")
	}
}

// TestParityMatterJS_ClosureControlServesEveryMandatoryAttribute pins that
// the server answers every attribute matter.js marks mandatory under the
// advertised feature set.
//
// A mandatory attribute the server does not resolve reads as "unsupported
// attribute", which a strict controller treats as a malformed cluster.
func TestParityMatterJS_ClosureControlServesEveryMandatoryAttribute(t *testing.T) {
	t.Parallel()
	js := closureSchema(t)
	srv := closure.NewControlServer(closure.Config{})

	served := make(map[uint32]bool)
	for _, id := range srv.MatterAttributes() {
		served[id] = true
	}

	for _, attr := range js.Attributes {
		if attr.Conformance != "M" {
			continue
		}
		if !served[attr.ID] {
			t.Errorf("attribute %s (0x%04X) is mandatory in matter.js HEAD but the server does not serve it",
				attr.Name, attr.ID)
			continue
		}
		if _, ok := srv.MatterRead(attr.ID); !ok {
			t.Errorf("attribute %s (0x%04X) is listed in MatterAttributes but MatterRead declines it",
				attr.Name, attr.ID)
		}
	}
}

// TestParityMatterJS_ControlServerListsOnlyServableAttributes is the
// reverse direction: an attribute the server advertises must actually
// resolve. The pair matters — either half alone passes with a list that
// has nothing to do with what MatterRead answers.
func TestParityMatterJS_ControlServerListsOnlyServableAttributes(t *testing.T) {
	t.Parallel()
	srv := closure.NewControlServer(closure.Config{})
	for _, id := range srv.MatterAttributes() {
		if _, ok := srv.MatterRead(id); !ok {
			t.Errorf("MatterAttributes lists 0x%04X but MatterRead declines it", id)
		}
	}
	for _, id := range srv.MatterReportable() {
		if _, ok := srv.MatterRead(id); !ok {
			t.Errorf("MatterReportable lists 0x%04X but MatterRead declines it", id)
		}
	}
}
